import pty, os, time, select, errno

def measure_delays(u_val):
    master, slave = pty.openpty()
    pid = os.fork()
    if pid == 0:
        os.close(master)
        os.setsid()
        os.dup2(slave, 0)
        os.dup2(slave, 1)
        os.dup2(slave, 2)
        os.close(slave)
        os.environ["TERM"] = "xterm-256color"
        os.execv("./executable", ["./executable", "-u", str(u_val)])
    else:
        os.close(slave)
        times = []
        t0 = time.time()
        while time.time() - t0 < 1.0:
            r, _, _ = select.select([master], [], [], 0.1)
            if r:
                try:
                    data = os.read(master, 4096)
                    if not data:
                        break
                    if b"\x1b[" in data:
                        times.append(time.time())
                except OSError:
                    break
        os.write(master, b"q")
        os.kill(pid, 9)
        os.waitpid(pid, 0)
        diffs = [times[i] - times[i-1] for i in range(1, len(times))]
        if diffs:
            avg_diff = sum(diffs) / len(diffs)
            print(f"-u {u_val}: avg delay between writes = {avg_diff:.4f}s ({1000*avg_diff:.1f}ms)")
        else:
            print(f"-u {u_val}: no frames")

for u in range(0, 11):
    measure_delays(u)
'"}

