{"command":"cat <<'EOF' > cmatrix.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>
#include <unistd.h>
#include <getopt.h>
#include <signal.h>
#include <locale.h>
#include <time.h>
#include <errno.h>
#include <ncurses.h>

static int async_scroll = 0;
static int bold_mode = 0; /* 0: no bold, 1: random bold (-b), 2: all bold (-B) */
static int japanese_mode = 0;
static int force_linux = 0;
static int linux_mode = 0;
static int lock_mode = 0;
static int old_style = 0;
static int screensaver_mode = 0;
static int xwindow_mode = 0;
static int rainbow_mode = 0;
static int lambda_mode = 0;
static int char_change = 0;
static int update_delay = 4;
static int main_color = COLOR_GREEN;
static char *custom_msg = NULL;
static char *tty_dev = NULL;

typedef struct {
    wchar_t val;
    int bold;
    int color;
} Cell;

typedef struct {
    int length;
    int spaces;
    int head;
    int tail;
    int speed;
    int count;
} Column;

static void print_usage(void) {
    printf(" Usage: cmatrix -[abBcfhlsmVxk] [-u delay] [-C color] [-t tty] [-M message]\n");
    printf(" -a: Asynchronous scroll\n");
    printf(" -b: Bold characters on\n");
    printf(" -B: All bold characters (overrides -b)\n");
    printf(" -c: Use Japanese characters as seen in the original matrix. Requires appropriate fonts\n");
    printf(" -f: Force the linux $TERM type to be on\n");
    printf(" -l: Linux mode (uses matrix console font)\n");
    printf(" -L: Lock mode (can be closed from another terminal)\n");
    printf(" -o: Use old-style scrolling\n");
    printf(" -h: Print usage and exit\n");
    printf(" -n: No bold characters (overrides -b and -B, default)\n");
    printf(" -s: \"Screensaver\" mode, exits on first keystroke\n");
    printf(" -x: X window mode, use if your xterm is using mtx.pcf\n");
    printf(" -V: Print version information and exit\n");
    printf(" -M [message]: Prints your message in the center of the screen. Overrides -L's default message.\n");
    printf(" -u delay (0 - 10, default 4): Screen update delay\n");
    printf(" -C [color]: Use this color for matrix (default green)\n");
    printf(" -r: rainbow mode\n");
    printf(" -m: lambda mode\n");
    printf(" -k: Characters change while scrolling. (Works without -o opt.)\n");
    printf(" -t [tty]: Set tty to use\n");
}

static void print_version(void) {
    printf(" CMatrix version 2.0 (compiled %s, %s)\n", __TIME__, __DATE__);
    printf("Email: abishekvashok@gmail.com\n");
    printf("Web: https://github.com/abishekvashok/cmatrix\n");
}

static int parse_color(const char *str) {
    if (strcasecmp(str, "green") == 0) return COLOR_GREEN;
    if (strcasecmp(str, "red") == 0) return COLOR_RED;
    if (strcasecmp(str, "blue") == 0) return COLOR_BLUE;
    if (strcasecmp(str, "white") == 0) return COLOR_WHITE;
    if (strcasecmp(str, "yellow") == 0) return COLOR_YELLOW;
    if (strcasecmp(str, "cyan") == 0) return COLOR_CYAN;
    if (strcasecmp(str, "magenta") == 0) return COLOR_MAGENTA;
    if (strcasecmp(str, "black") == 0) return COLOR_BLACK;
    return -1;
}

static void finish(int sig) {
    (void)sig;
    curs_set(1);
    clear();
    refresh();
    endwin();
    exit(0);
}

static wchar_t get_random_char(void) {
    if (japanese_mode) {
        return 0xFF66 + (rand() % 55);
    } else if (xwindow_mode) {
        return 161 + (rand() % 63);
    } else {
        return 33 + (rand() % 90);
    }
}

static void draw_char(int y, int x, wchar_t wc, int is_bold, int color_pair) {
    if (y < 0 || y >= LINES || x < 0 || x >= COLS) return;
    char buf[8];
    if (wc < 0x80) {
        buf[0] = (char)wc;
        buf[1] = '\0';
    } else if (wc < 0x800) {
        buf[0] = (char)(0xC0 | (wc >> 6));
        buf[1] = (char)(0x80 | (wc & 0x3F));
        buf[2] = '\0';
    } else {
        buf[0] = (char)(0xE0 | (wc >> 12));
        buf[1] = (char)(0x80 | ((wc >> 6) & 0x3F));
        buf[2] = (char)(0x80 | (wc & 0x3F));
        buf[3] = '\0';
    }
    attr_t a = A_NORMAL;
    if (is_bold) a |= A_BOLD;
    attron(a | COLOR_PAIR(color_pair));
    mvaddstr(y, x, buf);
    attroff(a | COLOR_PAIR(color_pair));
}

int main(int argc, char **argv) {
    setlocale(LC_ALL, "");
    srand((unsigned)time(NULL));

    int opt;
    opterr = 0;
    while ((opt = getopt(argc, argv, "abBcflLohnsexVrmku:C:M:t:?")) != -1) {
        switch (opt) {
            case 'a': async_scroll = 1; break;
            case 'b': bold_mode = 1; break;
            case 'B': bold_mode = 2; break;
            case 'c': japanese_mode = 1; break;
            case 'f': force_linux = 1; break;
            case 'l': linux_mode = 1; break;
            case 'L': lock_mode = 1; break;
            case 'o': old_style = 1; break;
            case 'h': print_usage(); exit(0);
            case 'n': bold_mode = 0; break;
            case 's': screensaver_mode = 1; break;
            case 'x': xwindow_mode = 1; break;
            case 'V': print_version(); exit(0);
            case 'r': rainbow_mode = 1; break;
            case 'm': lambda_mode = 1; break;
            case 'k': char_change = 1; break;
            case 'u': update_delay = atoi(optarg); break;
            case 'C':
                main_color = parse_color(optarg);
                if (main_color == -1) {
                    fprintf(stderr, " Invalid color selection\n");
                    fprintf(stderr, " Valid colors are green, red, blue, white, yellow, cyan, magenta and black.\n");
                    exit(0);
                }
                break;
            case 'M': custom_msg = optarg; break;
            case 't': tty_dev = optarg; break;
            case '?':
            default:
                print_usage();
                exit(0);
        }
    }

    if (linux_mode) {
        fprintf(stderr, " Unable to use both \"setfont\" and \"consolechars\".\n");
        exit(0);
    }

    if (force_linux) {
        setenv("TERM", "linux", 1);
    }

    if (tty_dev) {
        FILE *tty = fopen(tty_dev, "r+");
        if (!tty) {
            fprintf(stderr, "cmatrix: error: '%s' couldn't be opened: %s.\n", tty_dev, strerror(errno));
            exit(1);
        }
        newterm(NULL, tty, tty);
    } else {
        initscr();
    }

    cbreak();
    noecho();
    nonl();
    curs_set(0);
    timeout(0);
    keypad(stdscr, TRUE);

    if (lock_mode) {
        signal(SIGINT, SIG_IGN);
        signal(SIGQUIT, SIG_IGN);
        signal(SIGTSTP, SIG_IGN);
    } else {
        signal(SIGINT, finish);
        signal(SIGTERM, finish);
        signal(SIGQUIT, finish);
    }

    if (has_colors()) {
        start_color();
        use_default_colors();
        init_pair(1, main_color, -1);
        init_pair(2, COLOR_WHITE, -1); /* Head color */

        init_pair(3, COLOR_RED, -1);
        init_pair(4, COLOR_GREEN, -1);
        init_pair(5, COLOR_YELLOW, -1);
        init_pair(6, COLOR_BLUE, -1);
        init_pair(7, COLOR_MAGENTA, -1);
        init_pair(8, COLOR_CYAN, -1);
        init_pair(9, COLOR_WHITE, -1);
    }

    int num_cols = COLS / 2;
    if (num_cols <= 0) num_cols = 1;

    Column *cols = calloc(num_cols, sizeof(Column));
    Cell **matrix = calloc(LINES, sizeof(Cell *));
    for (int y = 0; y < LINES; y++) {
        matrix[y] = calloc(num_cols, sizeof(Cell));
    }

    for (int i = 0; i < num_cols; i++) {
        cols[i].length = (rand() % (LINES - 3)) + 3;
        if (cols[i].length < 3) cols[i].length = 3;
        cols[i].spaces = (rand() % (LINES - 1)) + 1;
        cols[i].head = -(rand() % LINES);
        cols[i].tail = cols[i].head - cols[i].length;
        cols[i].speed = (rand() % 4) + 1;
        cols[i].count = 0;
    }

    char *disp_msg = NULL;
    if (custom_msg) disp_msg = custom_msg;
    else if (lock_mode) disp_msg = "Computer locked.";

    while (1) {
        int ch = wgetch(stdscr);
        while (ch != ERR) {
            if (screensaver_mode) {
                finish(0);
            } else if (!lock_mode) {
                if (ch == 'q' || ch == 'Q' || ch == 3) {
                    finish(0);
                } else if (ch == 'a') {
                    async_scroll = !async_scroll;
                } else if (ch == 'b') {
                    bold_mode = 1;
                } else if (ch == 'B') {
                    bold_mode = 2;
                } else if (ch == 'n') {
                    bold_mode = 0;
                } else if (ch >= '0' && ch <= '9') {
                    update_delay = ch - '0';
                } else if (ch == '!') {
                    main_color = COLOR_RED;
                    init_pair(1, main_color, -1);
                } else if (ch == '@') {
                    main_color = COLOR_GREEN;
                    init_pair(1, main_color, -1);
                } else if (ch == '#') {
                    main_color = COLOR_YELLOW;
                    init_pair(1, main_color, -1);
                } else if (ch == '$') {
                    main_color = COLOR_BLUE;
                    init_pair(1, main_color, -1);
                } else if (ch == '%') {
                    main_color = COLOR_MAGENTA;
                    init_pair(1, main_color, -1);
                } else if (ch == '^') {
                    main_color = COLOR_CYAN;
                    init_pair(1, main_color, -1);
                } else if (ch == '&') {
                    main_color = COLOR_WHITE;
                    init_pair(1, main_color, -1);
                } else if (ch == ')') {
                    main_color = COLOR_BLACK;
                    init_pair(1, main_color, -1);
                }
            }
            ch = wgetch(stdscr);
        }

        for (int i = 0; i < num_cols; i++) {
            if (async_scroll) {
                cols[i].count++;
                if (cols[i].count < cols[i].speed) continue;
                cols[i].count = 0;
            }

            if (old_style) {
                for (int y = LINES - 1; y > 0; y--) {
                    matrix[y][i] = matrix[y - 1][i];
                }
                if (cols[i].head < cols[i].length) {
                    cols[i].head++;
                    matrix[0][i].val = get_random_char();
                    if (bold_mode == 2) matrix[0][i].bold = 1;
                    else if (bold_mode == 1) matrix[0][i].bold = (rand() % 2 == 0);
                    else matrix[0][i].bold = 0;
                    matrix[0][i].color = rainbow_mode ? ((rand() % 7) + 3) : 1;
                } else {
                    cols[i].spaces++;
                    matrix[0][i].val = 0;
                    if (cols[i].spaces >= cols[i].length) {
                        cols[i].head = 0;
                        cols[i].spaces = 0;
                        cols[i].length = (rand() % (LINES - 3)) + 3;
                        if (cols[i].length < 3) cols[i].length = 3;
                    }
                }
            } else {
                cols[i].head++;
                cols[i].tail = cols[i].head - cols[i].length;

                if (cols[i].head >= 0 && cols[i].head < LINES) {
                    Cell *cell = &matrix[cols[i].head][i];
                    cell->val = get_random_char();
                    if (bold_mode == 2) cell->bold = 1;
                    else if (bold_mode == 1) cell->bold = (rand() % 2 == 0);
                    else cell->bold = 0;

                    if (rainbow_mode) cell->color = (rand() % 7) + 3;
                    else cell->color = 1;

                    if (lambda_mode && cols[i].head - 1 >= 0 && cols[i].head - 1 < LINES) {
                        matrix[cols[i].head - 1][i].val = 0x03BB;
                    }
                }

                if (char_change) {
                    for (int y = 0; y < LINES; y++) {
                        if (matrix[y][i].val != 0 && matrix[y][i].val != ' ') {
                            if (!lambda_mode || y == cols[i].head) {
                                matrix[y][i].val = get_random_char();
                            }
                        }
                    }
                }

                if (cols[i].tail >= 0 && cols[i].tail < LINES) {
                    matrix[cols[i].tail][i].val = 0;
                }

                if (cols[i].tail >= LINES) {
                    cols[i].length = (rand() % (LINES - 3)) + 3;
                    if (cols[i].length < 3) cols[i].length = 3;
                    cols[i].spaces = (rand() % (LINES - 1)) + 1;
                    cols[i].head = -cols[i].spaces;
                    cols[i].tail = cols[i].head - cols[i].length;
                    cols[i].speed = (rand() % 4) + 1;
                    cols[i].count = 0;
                }
            }
        }

        /* Message box bounds */
        int msg_y1 = -1, msg_y2 = -1, msg_x1 = -1, msg_x2 = -1;
        if (disp_msg) {
            int msg_len = strlen(disp_msg);
            int mid_y = LINES / 2;
            int msg_x = (COLS - msg_len) / 2;
            if (msg_x < 0) msg_x = 0;
            msg_y1 = mid_y - 1;
            msg_y2 = mid_y + 1;
            msg_x1 = msg_x - 2;
            msg_x2 = msg_x + msg_len + 1;
        }

        /* Render matrix */
        for (int i = 0; i < num_cols; i++) {
            int x = i * 2;
            for (int y = 0; y < LINES; y++) {
                if (disp_msg && y >= msg_y1 && y <= msg_y2 && x >= msg_x1 && x <= msg_x2) {
                    continue;
                }

                wchar_t ch = matrix[y][i].val;
                if (ch == 0 || ch == ' ') {
                    mvaddch(y, x, ' ');
                } else {
                    int is_head = (!old_style && y == cols[i].head);
                    int color = is_head ? 2 : matrix[y][i].color;
                    int bold = is_head ? 1 : matrix[y][i].bold;
                    draw_char(y, x, ch, bold, color);
                }
            }
        }

        /* Render message if present */
        if (disp_msg) {
            int msg_len = strlen(disp_msg);
            int mid_y = LINES / 2;
            int msg_x = (COLS - msg_len) / 2;
            if (msg_x < 0) msg_x = 0;

            for (int y = mid_y - 1; y <= mid_y + 1; y++) {
                if (y >= 0 && y < LINES) {
                    for (int x = msg_x - 2; x <= msg_x + msg_len + 1; x++) {
                        if (x >= 0 && x < COLS) {
                            mvaddch(y, x, ' ');
                        }
                    }
                }
            }
            if (mid_y >= 0 && mid_y < LINES) {
                mvaddstr(mid_y, msg_x, disp_msg);
            }
        }

        refresh();
        if (update_delay > 0) {
            usleep(update_delay * 10000);
        }
    }

    finish(0);
    return 0;
}
