                } else if (ch >= '0' && ch <= '9') {
                    update_delay = ch - '0';
                } else if (ch == '!') {
                    main_color = COLOR_RED;
                    init_pair(1, main_color, -1);
                } else if (ch == '@') {
                    main_color = COLOR_GREEN;
                    init_pair(1, main_color, -1);
                } else if (ch == '#') {
                    main_color = COLOR_YELLOW;
                    init_pair(1, main_color, -1);
                } else if (ch == '$') {
                    main_color = COLOR_BLUE;
                    init_pair(1, main_color, -1);
                } else if (ch == '%') {
                    main_color = COLOR_MAGENTA;
                    init_pair(1, main_color, -1);
                } else if (ch == '^') {
                    main_color = COLOR_CYAN;
                    init_pair(1, main_color, -1);
                } else if (ch == '&') {
                    main_color = COLOR_WHITE;
                    init_pair(1, main_color, -1);
                } else if (ch == ')') {
                    main_color = COLOR_BLACK;
                    init_pair(1, main_color, -1);
                }
            }
            ch = wgetch(stdscr);
        }

        for (int i = 0; i < num_cols; i++) {
            if (async_scroll) {
                cols[i].count++;
                if (cols[i].count < cols[i].speed) continue;
                cols[i].count = 0;
            }

            if (old_style) {
                for (int y = LINES - 1; y > 0; y--) {
                    matrix[y][i] = matrix[y - 1][i];
                }
                if (cols[i].head < cols[i].length) {
                    cols[i].head++;
                    matrix[0][i].val = get_random_char();
                    if (bold_mode == 2) matrix[0][i].bold = 1;
                    else if (bold_mode == 1) matrix[0][i].bold = (rand() % 2 == 0);
                    else matrix[0][i].bold = 0;
                    matrix[0][i].color = rainbow_mode ? ((rand() % 7) + 3) : 1;
                } else {
                    cols[i].spaces++;
                    matrix[0][i].val = 0;
                    if (cols[i].spaces >= cols[i].length) {
                        cols[i].head = 0;
                        cols[i].spaces = 0;
                        cols[i].length = (rand() % (LINES - 3)) + 3;
                        if (cols[i].length < 3) cols[i].length = 3;
                    }
                }
            } else {
                cols[i].head++;
                cols[i].tail = cols[i].head - cols[i].length;

                if (cols[i].head >= 0 && cols[i].head < LINES) {
                    Cell *cell = &matrix[cols[i].head][i];
                    cell->val = get_random_char();
                    if (bold_mode == 2) cell->bold = 1;
                    else if (bold_mode == 1) cell->bold = (rand() % 2 == 0);
                    else cell->bold = 0;

                    if (rainbow_mode) cell->color = (rand() % 7) + 3;
                    else cell->color = 1;

                    if (lambda_mode && cols[i].head - 1 >= 0 && cols[i].head - 1 < LINES) {
                        matrix[cols[i].head - 1][i].val = 0x03BB;
                    }
                }

                if (char_change) {
                    for (int y = 0; y < LINES; y++) {
                        if (matrix[y][i].val != 0 && matrix[y][i].val != ' ') {
                            if (!lambda_mode || y == cols[i].head) {
                                matrix[y][i].val = get_random_char();
                            }
                        }
                    }
                }

                if (cols[i].tail >= 0 && cols[i].tail < LINES) {
                    matrix[cols[i].tail][i].val = 0;
                }

                if (cols[i].tail >= LINES) {
                    cols[i].length = (rand() % (LINES - 3)) + 3;
                    if (cols[i].length < 3) cols[i].length = 3;
                    cols[i].spaces = (rand() % (LINES - 1)) + 1;
                    cols[i].head = -cols[i].spaces;
                    cols[i].tail = cols[i].head - cols[i].length;
                    cols[i].speed = (rand() % 4) + 1;
                    cols[i].count = 0;
                }
            }
        }

        /* Message box bounds */
        int msg_y1 = -1, msg_y2 = -1, msg_x1 = -1, msg_x2 = -1;
        if (disp_msg) {
            int msg_len = strlen(disp_msg);
            int mid_y = LINES / 2;
            int msg_x = (COLS - msg_len) / 2;
            if (msg_x < 0) msg_x = 0;
            msg_y1 = mid_y - 1;
            msg_y2 = mid_y + 1;
            msg_x1 = msg_x - 2;
            msg_x2 = msg_x + msg_len + 1;
        }

        /* Render matrix */
        for (int i = 0; i < num_cols; i++) {
            int x = i * 2;
            for (int y = 0; y < LINES; y++) {
                if (disp_msg && y >= msg_y1 && y <= msg_y2 && x >= msg_x1 && x <= msg_x2) {
                    continue;
                }

                wchar_t ch = matrix[y][i].val;
                if (ch == 0 || ch == ' ') {
                    mvaddch(y, x, ' ');
                } else {
                    int is_head = (!old_style && y == cols[i].head);
                    int color = is_head ? 2 : matrix[y][i].color;
                    int bold = is_head ? 1 : matrix[y][i].bold;
                    draw_char(y, x, ch, bold, color);
                }
            }
        }

        /* Render message if present */
        if (disp_msg) {
            int msg_len = strlen(disp_msg);
            int mid_y = LINES / 2;
            int msg_x = (COLS - msg_len) / 2;
            if (msg_x < 0) msg_x = 0;

            for (int y = mid_y - 1; y <= mid_y + 1; y++) {
                if (y >= 0 && y < LINES) {
                    for (int x = msg_x - 2; x <= msg_x + msg_len + 1; x++) {
                        if (x >= 0 && x < COLS) {
                            mvaddch(y, x, ' ');
                        }
                    }
                }
            }
            if (mid_y >= 0 && mid_y < LINES) {
                mvaddstr(mid_y, msg_x, disp_msg);
            }
        }

        refresh();
        if (update_delay > 0) {
            usleep(update_delay * 10000);
        }
    }

    finish(0);
    return 0;
}
